package com.crmconnect.connection; import jakarta.validation.constraints.NotBlank; public class ConnectionRequest { @NotBlank private String firstName; @NotBlank private String lastName; private String email,phone,companyName; private Connection.Source source=Connection.Source.OTHER; private Connection.Status status=Connection.Status.LEAD; private Long assignedToUserId; public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getCompanyName(){return companyName;} public void setCompanyName(String v){companyName=v;} public Connection.Source getSource(){return source;} public void setSource(Connection.Source v){source=v;} public Connection.Status getStatus(){return status;} public void setStatus(Connection.Status v){status=v;} public Long getAssignedToUserId(){return assignedToUserId;} public void setAssignedToUserId(Long v){assignedToUserId=v;} }
